create or replace function public.list_stolen_web_orders() returns setof public.web_orders language plpgsql security definer set search_path = public as $$ begin if auth.role() <> 'service_role' then raise exception 'not_service' using errcode = '42501'; end if; return query select * from public.web_orders where status = 'stolen' and payment_id is not null and refund_id is null; end; $$;
create or replace function public.mark_web_order_boxed(p_id uuid) returns public.web_orders language plpgsql security definer set search_path = public as $$ declare v_row public.web_orders; begin perform public.assert_staff_or_service(); update public.web_orders set boxed_at = coalesce(boxed_at, now()), updated_at = now() where id = p_id and store_id = public.current_store_id() and status = 'paid' and boxed_at is null returning * into v_row; if not found then raise exception 'not_boxable' using errcode = 'P0001'; end if; return v_row; end; $$;
create or replace function public.mark_web_order_shipped(p_id uuid, p_tracking text) returns public.web_orders language plpgsql security definer set search_path = public as $$ declare v_row public.web_orders; begin perform public.assert_staff_or_service(); if p_tracking is null or btrim(p_tracking) = '' then raise exception 'tracking_required' using errcode = '22023'; end if; update public.web_orders set shipped_at = coalesce(shipped_at, now()), tracking_number = btrim(p_tracking), updated_at = now() where id = p_id and store_id = public.current_store_id() and status = 'paid' and boxed_at is not null returning * into v_row; if not found then raise exception 'not_shippable' using errcode = 'P0001'; end if; insert into public.alert_outbox (store_id, kind, sku, payload) values (v_row.store_id, 'web_shipped', v_row.sku, jsonb_build_object('order_id', v_row.id, 'buyer_email', v_row.buyer_email, 'buyer_name', v_row.buyer_name, 'tracking', v_row.tracking_number)); return v_row; end; $$;
create or replace function public.update_unit_field(p_sku text, p_field text, p_value text) returns void language plpgsql security definer set search_path = public as $$ declare v_store uuid := public.current_store_id(); v_old text; v_cost_fields text[] := array['acquisition_cost_cents', 'floor_cents']; begin perform public.assert_staff_or_service(); if p_field = any (v_cost_fields) and not public.is_manager() then raise exception 'not_manager' using errcode = '42501'; end if; if p_field not in ('brand','model','title','category','condition','test_status','location','mfr_serial','defect_notes','upc','lot','acquisition_cost_cents','msrp_cents','ask_cents','floor_cents','listing_body','listing_specs','show_on_website','shippable','shipping_cents') then raise exception 'invalid_field' using errcode = '22023'; end if; execute format('select %I::text from public.units where sku = $1 and store_id = $2', p_field) into v_old using p_sku, v_store; if p_field like '%_cents' then execute format('update public.units set %I = $1::int, updated_at = now() where sku = $2 and store_id = $3', p_field) using nullif(p_value, ''), p_sku, v_store; elsif p_field = 'listing_specs' then update public.units set listing_specs = nullif(p_value, '')::jsonb, updated_at = now() where sku = p_sku and store_id = v_store; elsif p_field in ('show_on_website', 'shippable') then execute format('update public.units set %I = $1, updated_at = now() where sku = $2 and store_id = $3', p_field) using (lower(coalesce(p_value, '')) in ('true', '1', 't', 'yes', 'on')), p_sku, v_store; else execute format('update public.units set %I = $1, updated_at = now() where sku = $2 and store_id = $3', p_field) using p_value, p_sku, v_store; end if; insert into public.events (store_id, sku, kind, field, old_value, new_value, actor, actor_id) values (v_store, p_sku, 'edit', p_field, v_old, p_value, coalesce((select display_name from public.staff where user_id = auth.uid()), 'staff'), auth.uid()); end; $$;
grant execute on function public.list_stolen_web_orders() to service_role;
grant execute on function public.mark_web_order_stolen_refund(uuid, text) to service_role;
grant execute on function public.mark_web_order_boxed(uuid) to authenticated;
grant execute on function public.mark_web_order_shipped(uuid, text) to authenticated;;
